CREATE TABLE "controller_instances" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "instance_id" character varying NOT NULL, "version" character varying NOT NULL, "migration_head" character varying NOT NULL, "host" character varying NOT NULL DEFAULT '', "started_unix" bigint NOT NULL, "last_seen_unix" bigint NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "controller_instances_instance_id_key" ON "controller_instances" ("instance_id");
CREATE INDEX "controllerinstance_last_seen_unix" ON "controller_instances" ("last_seen_unix");
